 // hist[b] = number of i < n with (in[i] & 255) == b for b < 256. Neither out nor
 // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
 // never overflow int64.
+constexpr int HIST_SUBS = 8;  // Number of private sub-histograms (tunable)
+constexpr int UNROLL = 8;     // Elements processed per loop iteration (tunable)
+
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
-    for (int b = 0; b < 256; ++b) hist[b] = 0;
-    int64_t sum = 0;
-    for (size_t i = 0; i < n; ++i) {
-        sum += in[i];
-        out[i] = sum;
-        hist[in[i] & 255]++;
+    // Initialize histogram with 8 sub-histograms (uint32_t to avoid overflow per chunk)
+    uint32_t sub_hist[HIST_SUBS][256];
+    memset(sub_hist, 0, sizeof(sub_hist));
+    
+    // Zero main histogram
+    memset(hist, 0, 256 * sizeof(uint64_t));
+    
+    int64_t running_sum = 0;
+    size_t i = 0;
+    
+    // Process 8 elements per iteration
+    const size_t vec_loop_limit = n & ~(size_t)7;
+    
+    for (; i < vec_loop_limit; i += 8) {
+        // Load 8 elements
+        int64_t v0 = in[i];
+        int64_t v1 = in[i+1];
+        int64_t v2 = in[i+2];
+        int64_t v3 = in[i+3];
+        int64_t v4 = in[i+4];
+        int64_t v5 = in[i+5];
+        int64_t v6 = in[i+6];
+        int64_t v7 = in[i+7];
+        
+        // Inclusive scan with running sum
+        running_sum += v0; out[i] = running_sum;
+        running_sum += v1; out[i+1] = running_sum;
+        running_sum += v2; out[i+2] = running_sum;
+        running_sum += v3; out[i+3] = running_sum;
+        running_sum += v4; out[i+4] = running_sum;
+        running_sum += v5; out[i+5] = running_sum;
+        running_sum += v6; out[i+6] = running_sum;
+        running_sum += v7; out[i+7] = running_sum;
+        
+        // Histogram: distribute 8 elements across 8 sub-histograms
+        // Element i+k goes to sub_hist[k][in[i+k] & 255]
+        sub_hist[0][v0 & 255]++;
+        sub_hist[1][v1 & 255]++;
+        sub_hist[2][v2 & 255]++;
+        sub_hist[3][v3 & 255]++;
+        sub_hist[4][v4 & 255]++;
+        sub_hist[5][v5 & 255]++;
+        sub_hist[6][v6 & 255]++;
+        sub_hist[7][v7 & 255]++;
+    }
+    
+    // Process remaining elements
+    for (; i < n; ++i) {
+        running_sum += in[i];
+        out[i] = running_sum;
+        sub_hist[i % HIST_SUBS][in[i] & 255]++;
+    }
+    
+    // Combine sub-histograms into final histogram
+    for (int s = 0; s < HIST_SUBS; ++s) {
+        for (int b = 0; b < 256; ++b) {
+            hist[b] += sub_hist[s][b];
+        }
     }
 }
